package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerHouseholdException;

/**
 * Rejects a create request that shares another owner's household: same last name and address,
 * compared case-insensitively with collapsed whitespace. A request with {@code sharesHousehold}
 * true opts out of the check. A match rejects 409.
 */
public class RequireUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        for (Owner owner : ownerRepository.findAll()) {
            if (lastName.equals(normalize(owner.getLastName()))
                    && address.equals(AddressNormalizer.normalize(owner.getAddress()))) {
                throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
            }
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
=== NormalizeOwnerTelephone ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Rewrites the create request's telephone into E.164 form, storing it in place. Spaces, dashes and
 * brackets are stripped; a leading '+' and country code are kept, otherwise country code '+61' is
 * assumed and a single leading '0' is dropped from the national digits. Runs before {@link BuildOwner},
 * so the entity and the response both carry the E.164 form; anything that cannot yield 8 to 15 digits
 * after the '+' rejects with 400.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
        String cleaned = request.getTelephone().replaceAll("[\\s()\\-]", "");
        String e164;
        if (cleaned.startsWith("+")) {
            e164 = cleaned;
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            e164 = "+61" + national;
        }
        if (!e164.substring(1).matches("\\d{8,15}")) {
            throw new MissingOwnerFieldsException(List.of("telephone"));
        }
        request.setTelephone(e164);
    }
}
=== NormalizeOwnerEmail ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Optional email: when absent the request is untouched; when present it must be a syntactically
 * valid address, stored lower-cased in place so the entity and the response both carry it. An
 * invalid address rejects with 400 via {@link MissingOwnerFieldsException}.
 */
public class NormalizeOwnerEmail {

    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
        String email = request.getEmail();
        if (email == null) {
            return;
        }
        if (!EMAIL.matcher(email).matches()) {
            throw new MissingOwnerFieldsException(List.of("email"));
        }
        request.setEmail(email.toLowerCase());
    }
}
