package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Derives an owner's {@code identityKey}, the single value all duplicate detection is based on:
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two owners are duplicates
 * only when their WHOLE keys are equal, so household members with different telephones stay distinct.
 * The household segment matches {@code OwnerMapper.householdId} (normalized last name + address).
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    public static String key(String telephone, String email, String lastName, String address) {
        String tel = telephone == null ? "" : telephone;
        String mail = email == null ? "" : email.toLowerCase();
        String household = normalize(lastName) + "|" + AddressNormalizer.normalize(address);
        return tel + "|" + mail + "|" + String.format("H-%08X", household.hashCode());
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

